import boto3
import json

def get_model_output_with_metadata(prompt: str) -> dict:
    """
    Invokes a model on Amazon Bedrock and returns its output along with platform metadata.
    """

    bedrock_runtime = boto3.client(
        service_name="bedrock-runtime",
        region_name="us-east-1" # Or your desired AWS region
    )

    model_id = "anthropic.claude-3-sonnet-20240229-v1:0"

    # The request body format depends on the chosen model.
    # For Claude 3 Sonnet, it expects messages API format.
    body = json.dumps({
        "anthropic_version": "bedrock-2023-05-31",
        "messages": [
            {
                "role": "user",
                "content": [{"type": "text", "text": prompt}]
            }
        ],
        "max_tokens": 100
    })

    response = bedrock_runtime.invoke_model(
        body=body,
        modelId=model_id,
        accept="application/json",
        contentType="application/json"
    )

    response_body = json.loads(response["body"].read())

    model_output = ""
    for content_block in response_body.get("content", []):
        if content_block.get("type") == "text":
            model_output += content_block["text"]

    # Extract usage metadata
    usage_metadata = response_body.get("usage", {})

    return {
        "model_output": model_output.strip(),
        "provider_metadata": {
            "model_id": model_id,
            "usage": usage_metadata
        }
    }
